<?php
if(!defined('SCHOOLOS_EXPERIENCE')){http_response_code(404);exit;}
function px_live_scope(array $u,int $id,bool $join=false):array{$r=q('SELECT l.*,s.name subject,c.name class_name FROM px_live l JOIN classes c ON c.id=l.class_id AND c.tenant_id=l.tenant_id JOIN subjects s ON s.id=l.subject_id AND s.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.id=?',[$u['tenant_id'],$id])->fetch();if(!$r)throw new RuntimeException('Live lesson unavailable.');if($u['role']==='student'){$s=lp_student($u);if((int)$s['class_id']!==(int)$r['class_id']||$s['session_name']!==$r['session_name'])throw new RuntimeException('This lesson is outside your class and current session.');}elseif($u['role']==='teacher'){if((int)$r['teacher_id']!==(int)$u['id'])throw new RuntimeException('Only your own live lessons are available.');lp_scope($u,(int)$r['class_id'],(int)$r['subject_id'],$r['session_name']);}elseif($u['role']!=='school_admin')throw new RuntimeException('Teacher or learner access required.');if($join&&(in_array($r['status'],['ended','cancelled'],true)||strtotime($r['ends_at'])<=time()||strtotime($r['starts_at'])>time()+900))throw new RuntimeException('This lesson is outside its joining window.');return $r;}
function px_live_create(array $u):string{if(!in_array($u['role'],['teacher','school_admin'],true))throw new RuntimeException('Teacher required.');$class=(int)xp_text('class_id',20);$subject=(int)xp_text('subject_id',20);$a=lp_scope($u,$class,$subject);$start=lp_datetime(xp_text('starts_at',16));$end=lp_datetime(xp_text('ends_at',16));if(!$start||!$end||$end<=$start||strtotime($end)<=time()||strtotime($end)-strtotime($start)>14400)throw new RuntimeException('Choose a valid lesson window of up to four hours.');$provider=xp_text('provider',20);if(!in_array($provider,['schoolos','zoom','meet'],true))throw new RuntimeException('Choose a supported classroom provider.');$url=xp_text('join_url',1000,false);if($provider!=='schoolos'){$parts=parse_url($url);$host=strtolower($parts['host']??'');if(($parts['scheme']??'')!=='https'||isset($parts['user'])||isset($parts['pass'])||isset($parts['port'])||($provider==='meet'?$host!=='meet.google.com':!preg_match('/(^|\.)zoom\.us$/D',$host)))throw new RuntimeException('Use an HTTPS invitation URL from the selected Zoom or Google Meet provider.');}else $url=null;q('INSERT INTO px_live(tenant_id,teacher_id,class_id,subject_id,session_name,title,provider,join_url,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$u['tenant_id'],$u['id'],$class,$subject,$a['session_name'],xp_text('title',180),$provider,$url,$start,$end]);audit('learning.live.created');return 'Live lesson scheduled for the allocated class.';}
function px_live_join(array $u,int $id):array{xp_rate('live-join-'.$u['id'],10,5);return xp_tx(function()use($u,$id){q('SELECT id FROM px_live WHERE tenant_id=? AND id=? FOR UPDATE',[$u['tenant_id'],$id]);$r=px_live_scope($u,$id,true);if($r['provider']!=='schoolos')throw new RuntimeException('Open the lesson provider invitation instead.');q('DELETE FROM px_signals WHERE tenant_id=? AND created_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE) LIMIT 500',[$u['tenant_id']]);$host=(int)$r['teacher_id']===(int)$u['id'];if(!$host&&$u['role']!=='student')throw new RuntimeException('Only the scheduled host or allocated learners may join.');if(!$host&&($r['status']!=='live'||!g('SELECT user_id FROM px_peers WHERE tenant_id=? AND lesson_id=? AND user_id=? AND last_seen>DATE_SUB(NOW(),INTERVAL 35 SECOND)',[$u['tenant_id'],$id,$r['teacher_id']])))throw new RuntimeException('Your teacher has not started the live lesson yet.');$count=(int)g('SELECT COUNT(*) FROM px_peers WHERE tenant_id=? AND lesson_id=? AND user_id<>? AND last_seen>DATE_SUB(NOW(),INTERVAL 35 SECOND)',[$u['tenant_id'],$id,$u['id']]);if($count>=8)throw new RuntimeException('The small-group classroom has reached its eight-person capacity. Use a configured conferencing provider for larger classes.');if($host)q("UPDATE px_live SET status='live' WHERE tenant_id=? AND id=?",[$u['tenant_id'],$id]);$key=bin2hex(random_bytes(16));q('INSERT INTO px_peers(tenant_id,lesson_id,user_id,peer_key,last_seen) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE peer_key=VALUES(peer_key),last_seen=NOW()',[$u['tenant_id'],$id,$u['id'],$key]);$ice=[];$secrets=sv_secrets((int)$u['tenant_id']);$url=$secrets['classroom_turn_url']??'';$secret=$secrets['classroom_turn_secret']??'';if($url&&$secret){$username=(time()+3600).':schoolos-'.$u['tenant_id'].'-'.$u['id'];$ice[]=['urls'=>$url,'username'=>$username,'credential'=>base64_encode(hash_hmac('sha1',$username,$secret,true))];}return ['key'=>$key,'host'=>$host,'hostId'=>(int)$r['teacher_id'],'iceServers'=>$ice,'relayConfigured'=>(bool)$ice,'lesson'=>$id];});}
function px_peer(array $u,int $id,string $key):array{$r=px_live_scope($u,$id,true);$p=q('SELECT * FROM px_peers WHERE tenant_id=? AND lesson_id=? AND user_id=? AND peer_key=? AND last_seen>DATE_SUB(NOW(),INTERVAL 45 SECOND)',[$u['tenant_id'],$id,$u['id'],$key])->fetch();if(!$p)throw new RuntimeException('Classroom session expired. Please join again.');q('UPDATE px_peers SET last_seen=NOW() WHERE tenant_id=? AND lesson_id=? AND user_id=? AND peer_key=?',[$u['tenant_id'],$id,$u['id'],$key]);return $r;}
function px_live_poll(array $u,int $id,string $key,int $after):array{$r=px_peer($u,$id,$key);$peers=q('SELECT p.user_id,p.peer_key,u.name FROM px_peers p JOIN users u ON u.id=p.user_id AND u.tenant_id=p.tenant_id AND u.active=1 WHERE p.tenant_id=? AND p.lesson_id=? AND p.last_seen>DATE_SUB(NOW(),INTERVAL 35 SECOND) AND p.user_id<>?',[$u['tenant_id'],$id,$u['id']])->fetchAll();$signals=q('SELECT id,from_user,from_key,kind,payload FROM px_signals WHERE tenant_id=? AND lesson_id=? AND to_user=? AND to_key=? AND id>? AND created_at>DATE_SUB(NOW(),INTERVAL 2 MINUTE) ORDER BY id LIMIT 100',[$u['tenant_id'],$id,$u['id'],$key,max(0,$after)])->fetchAll();return ['peers'=>$peers,'signals'=>$signals,'status'=>$r['status']];}
function px_live_signal(array $u,int $id):void{$r=px_peer($u,$id,xp_text('key',32));$to=(int)xp_text('to',20);$target=q('SELECT * FROM px_peers WHERE tenant_id=? AND lesson_id=? AND user_id=? AND peer_key=? AND last_seen>DATE_SUB(NOW(),INTERVAL 35 SECOND)',[$u['tenant_id'],$id,$to,xp_text('to_key',32)])->fetch();if(!$target||$to===(int)$u['id']||((int)$u['id']!==(int)$r['teacher_id']&&$to!==(int)$r['teacher_id']))throw new RuntimeException('Signal recipient is outside this classroom relationship.');$kind=xp_text('kind',12);if(!in_array($kind,['offer','answer','ice'],true)||($kind==='offer'&&(int)$u['id']!==(int)$r['teacher_id'])||($kind==='answer'&&(int)$u['id']===(int)$r['teacher_id']))throw new RuntimeException('Unsupported classroom signal.');$payload=xp_text('payload',120000);$decoded=json_decode($payload,true);if(!is_array($decoded)||($kind!=='ice'&&(($decoded['type']??'')!==$kind||!is_string($decoded['sdp']??null)))||($kind==='ice'&&!is_string($decoded['candidate']??null)))throw new RuntimeException('Invalid classroom signal.');xp_rate('classroom-signal-'.$u['id'],180,1);q('INSERT INTO px_signals(tenant_id,lesson_id,from_user,to_user,from_key,to_key,kind,payload) VALUES(?,?,?,?,?,?,?,?)',[$u['tenant_id'],$id,$u['id'],$to,xp_text('key',32),$target['peer_key'],$kind,$payload]);}
function px_live_view(array $u):void{echo '<section class="px-live"><span class="px-kicker">MEET. LEARN. CONNECT.</span><h2>Your live classroom.</h2><p>Join your allocated class online. Teachers can schedule an existing Zoom / Google Meet invitation or use the small-group SchoolOS classroom.</p>';if(!px_ready()){echo '<p>Ask your school administrator to activate Portal Experience.</p></section>';return;}$host=in_array($u['role'],['teacher','school_admin'],true);if($host){echo '<details class="px-composer"><summary>Schedule a live lesson</summary><form method="post" class="lp-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="px_action" value="live_create">';lp_class_fields($u);lp_input('title','Lesson title');lp_select('provider','Classroom',['schoolos'=>'SchoolOS · eight-person teacher broadcast','meet'=>'Google Meet invitation link','zoom'=>'Zoom invitation link']);lp_input('join_url','Zoom / Meet HTTPS invitation (leave empty for SchoolOS)','url','',false);lp_input('starts_at','Starts at · WAT','datetime-local');lp_input('ends_at','Ends at · WAT','datetime-local');lp_end('Schedule lesson');echo '<p><a href="https://meet.google.com/new" target="_blank" rel="noopener noreferrer">Create a Google Meet invitation ↗</a> · <a href="https://zoom.us/meeting/schedule" target="_blank" rel="noopener noreferrer">Schedule in your Zoom account ↗</a></p><p>No provider account is created or charged by SchoolOS. Paste the invitation from your own provider account.</p></details>';}
$rows=q('SELECT id FROM px_live WHERE tenant_id=? AND ends_at>=DATE_SUB(NOW(),INTERVAL 1 DAY) ORDER BY starts_at LIMIT 100',[$u['tenant_id']])->fetchAll();echo '<div class="px-live-grid">';foreach($rows as $row){try{$r=px_live_scope($u,(int)$row['id']);}catch(Throwable){continue;}echo '<article class="px-live-card"><span class="px-badge">'.e($r['provider']).' · '.e($r['status']).'</span><h3>'.e($r['title']).'</h3><p>'.e($r['class_name'].' · '.$r['subject']).'</p><time>'.e(date('D, j M · H:i',strtotime($r['starts_at']))).' – '.e(date('H:i',strtotime($r['ends_at']))).' WAT</time>';if($r['provider']==='schoolos'){try{px_live_scope($u,(int)$r['id'],true);echo '<button type="button" class="btn" data-live-join="'.(int)$r['id'].'">'.($host?'Start / resume broadcast':'Join live lesson').'</button>';}catch(Throwable){echo '<p>This lesson is outside its joining window or has ended.</p>';}}else{try{px_live_scope($u,(int)$r['id'],true);echo '<a class="btn" href="'.e($r['join_url']).'" target="_blank" rel="noopener noreferrer">Join provider classroom ↗</a>';}catch(Throwable){echo '<p>Joining opens 15 minutes before the lesson.</p>';}}if($host&&$r['teacher_id']==$u['id']&&!in_array($r['status'],['ended','cancelled'],true))px_form('live_end','End this lesson',['lesson_id'=>$r['id']]);echo '</article>';}echo '</div><section class="px-video-stage" id="pxLiveStage" hidden><h3 id="pxLiveTitle">SchoolOS classroom</h3><div id="pxLiveStatus" role="status"></div><video id="pxLiveVideo" controls autoplay playsinline></video><div><button type="button" class="btn" id="pxShareScreen">Share screen</button><button type="button" class="btn" id="pxLiveLeave">Leave classroom</button></div><p>Learners receive the teacher’s stream; learner cameras and microphones are not requested. No recording is performed. Use school chat for questions.</p><a href="?s=chat">Open school conversations →</a></section><p class="px-connection-note">SchoolOS live is a small-group teacher broadcast. Camera/screen sharing needs HTTPS and browser permission. Without a relay, direct connectivity is limited to compatible networks; a school-controlled TURN service is required for reliable connections across different networks. The shared demo has its own optional relay configuration and never receives your live school’s relay secrets.</p>';
if($u['role']==='school_admin'){echo '<details><summary>Configure your school-controlled media relay</summary><form method="post" class="lp-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="px_action" value="live_settings">';lp_input('turn_url','TURN URL, for example turns:relay.yourschool.ng:5349','text','',false);lp_input('turn_secret','TURN shared authentication secret (stored encrypted)','password','',false);lp_end('Save media relay settings');echo '<p>Use a relay you control or have contracted. Endpoint and shared secret must use the provider’s expiring HMAC credential convention. An empty form leaves existing settings unchanged.</p></details>';}echo '</section><script src="classroom.js?v=530" defer></script>';}
